// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: a strictly positive, non-extreme amount is held by C.
        amount = bound(amount, 1, type(uint256).max / 2);

        // Fund the contract so the selfdestruct beneficiary actually receives value.
        vm.deal(address(c), amount);

        uint256 zeroBalBefore = address(0).balance;

        // setUp's msg.sender (this test contract) is __owner; drive the entry point.
        c.sudicideAnyone();

        // General rule: destroying C must never credit the zero address with funds.
        // Reference C: beneficiary is msg.sender (owner), zero-address balance unchanged.
        // Mutant M: beneficiary is address(0), which receives `amount` -> assertion breaks.
        assertTrue(address(0).balance == zeroBalBefore);
    }
}
